import hashlib
import itertools

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def crack_password(hashed_password):
    common_passwords = ['password', '123456', '12345678', '123456789', 'qwerty', 'letmein', 'dragonball','monkey', 'iloveyou', 'baseball']
    for password in common_passwords:
        if hash_password(password) == hashed_password:
            return password
    for length in range(1, 10):
        for chars in itertools.product('abcdefghijklmnopqrstuvwxyz', repeat=length):
            password = ''.join(chars)
            if hash_password(password) == hashed_password:
                return password
    return None

def main():
    hashed_password = input("Enter the hashed password: ")
    password = crack_password(hashed_password)
    if password is not None:
        print("The password is", password)
    else:
        print("The password is too long or too complex")

if __name__ == "__main__":
    main()
